rethrow.source:
namespace CleanCode.Examples;
internal static class LostStack
{
    internal static void Rethrow(Action action)
    {
        try
        {
            action();
        }
        catch (InvalidOperationException exception)
        {
            throw exception;
        }
    }
}

async-alternative.source:
namespace CleanCode.Examples;
internal static class BlockingRead
{
    internal static async Task<string> ReadAsync(string path)
    {
        string text = File.ReadAllText(path);
        await Task.Delay(1).ConfigureAwait(false);
        return text;
    }
}

valuetask-reuse.source:
namespace CleanCode.Examples;
internal static class ReusedValueTask
{
    internal static async Task<int> ReadAsync(Func<ValueTask<int>> getValue)
    {
        ValueTask<int> value = getValue();
        int first = await value.ConfigureAwait(false);
        return first + await value.ConfigureAwait(false);
    }
}

multiple-enumeration.source:
namespace CleanCode.Examples;
internal static class RepeatedSequence
{
    internal static int Total(IEnumerable<int> values)
    {
        int count = values.Count();
        return count + values.Sum();
    }
}

